(()=>{'use strict';
const KEY='dragon-throne-save-v2';const AI_ENDPOINT_DEFAULT='https://dragon-throne-ai.ranshervsingh.workers.dev';let aiEndpoint=sessionStorage.getItem('dragon-throne-ai-endpoint')||AI_ENDPOINT_DEFAULT;let aiToken=sessionStorage.getItem('dragon-throne-ai-token')||'';let aiBusy=false;const BASE={year:1445,month:1,turn:0,orders:[],custom:[],notes:{},history:[],transcript:null,characterProfiles:{},appointments:[],candidateIntroductions:[]};let state;try{state={...BASE,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state={...BASE}}let campaign=null;let path=['Empire'],search='',archive='',archiveStatus='Loading bundled historical transcript…',selectedProvince='Beijing';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>new Intl.NumberFormat('en-US').format(n);const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){alert('Storage full. Export your save before continuing.')}};const go=s=>{path.push(s);render();window.scrollTo(0,0)};const root=s=>{path=['Empire',s].filter((x,i)=>i===0||x!=='Empire');render();window.scrollTo(0,0)};const back=()=>{if(path.length>1)path.pop();render()};const menu={Empire:['World Map','Military','Economy','Court','Characters & Dynasty','Inner Palace','Technology','Diplomacy','Institutions','Chronicle','Campaign Checkpoint','Game & Saves'],Military:['Military Overview','Armies & Garrisons','Unit Types','Commanders','Logistics & Supply','Equipment & Arsenals','Navy','Military Expenditure','Reforms & Exercises'], 'Armies & Garrisons':["Prince Yan's Training Formation",'Professional Army Pilot','Frontier Garrisons','Other Field Forces'],"Prince Yan's Training Formation":['Formation Overview','Unit Composition','Location & Deployment','Commander & Staff','Supply & Equipment','Training & Orders','Formation Costs','Service History'],'Unit Composition':['Infantry & Firearms','Cavalry','Artillery & Engineers','Logistics & Transport','Medical, Signals & Administration'],'Economy':['Economic Overview','Revenue','Expenditure','Treasury & Reserves','Investment House','Mining Company',"Soldiers' Bank",'Trade & Commerce','Agriculture & Public Works'],'Revenue':['Revenue Overview','Land Revenue','Commercial Revenue','Trade & Customs','Other Revenue'],'Expenditure':['Expenditure Overview','Recurring Expenditure','Extraordinary Payments','Military Expenditure','Public Works & Industry','Civil Administration','Historical Changes'],'Recurring Expenditure':['Military Recurring Costs','Civil Recurring Costs','Other Recurring Costs'],'Extraordinary Payments':['Industrial Academy & Steam','Military Logistics Reform','Agricultural Improvements','Military Audit','Diplomatic & Household Missions','Prior Commitments'],'Treasury & Reserves':['Treasury Overview','Uncommitted Liquidity','Restricted Reserves','Outstanding Commitments','Liquidity Policy'],'Investment House':['Company Overview','Cash & Assets','Portfolio & Subsidiaries','Dividends & Returns','Investment Decisions'],'Mining Company':['Mining Overview','Assets & Cash','Gold & Mineral Prospects','Mining Investments'],"Soldiers' Bank":['Bank Overview','Deposits & Liabilities','Loans & Risk Controls'],'Characters & Dynasty':['Character Directory','Marriage Candidates','Appointment Council','Family & Succession','Character Chronicle'], 'Character Directory':['Crown Prince Jing','Prince Yan','Xia Yuanji','Zhang Fu','Yang Shiqi','Empress Shen','Noble Consort Wang','Dilshad','Ratna'], 'Marriage Candidates':['Lady Lin','Lady Zhao','Lady Wu'], 'Appointment Council':['Minister of Revenue','Minister of War','Provincial Governor','Diplomatic Envoy','Military Commander'], 'Family & Succession':['Crown Prince Jing','Prince Yan','Empress Shen','Noble Consort Wang'], 'Character Chronicle':['Recorded Audiences','Character Notes'], 'Court':['Imperial Council','Crown Prince Jing','Prince Yan','Xia Yuanji','Zhang Fu','Yang Shiqi','Appointments & Offices','Court Audiences'],'Inner Palace':['Empress Shen','Noble Consort Wang','Dilshad','Ratna','Imperial Children','Household Affairs','Dynastic Succession'],'Technology':['Steam Engines','Iron & Metallurgy','Printing','Agricultural Machinery','Scientific Academies','Research Priorities'],'Diplomacy':['Foreign Relations','Embassies & Missions','Maritime Trade','Treaties & Negotiations'],'Institutions':['Institution Register','Create Institution','Imperial Investment House','Mining Company',"Soldiers' Bank",'Roads & Granaries','Highways & Couriers','Eastern Seas Trading','Agricultural Machinery & Waterworks','Precision Ironworks'],'Campaign Checkpoint':['Start 1445','1444 Closing Accounts','1445 Council Agenda','Recorded Characters','Known Unknowns'], 'Chronicle':['Timeline & Orders','Historical Transcript','Search Chronicle','1440','1441','1442','1443','1444'],'Game & Saves':['AI Connection','Export Save','Import Save','Import Transcript','About & Limitations']};
const provinces=[{n:'Beijing',x:310,y:120,info:'Imperial capital; court and recorded training formation (1441).',army:true},{n:'Shandong',x:400,y:174,info:'Eastern coastal province; detailed fiscal and garrison figures unverified.'},{n:'Shanxi',x:238,y:174,info:'Northern province; detailed records unverified.'},{n:'Shaanxi',x:172,y:260,info:'Northwestern province; detailed records unverified.'},{n:'Henan',x:320,y:248,info:'Central plains; detailed records unverified.'},{n:'Jiangsu',x:440,y:290,info:'Lower Yangtze; detailed records unverified.'},{n:'Zhejiang',x:482,y:361,info:'Coastal province; detailed records unverified.'},{n:'Huguang',x:313,y:354,info:'Middle Yangtze; detailed records unverified.'},{n:'Sichuan',x:175,y:362,info:'Western basin; detailed records unverified.'},{n:'Guangdong',x:358,y:465,info:'Southern maritime province; detailed records unverified.'},{n:'Yunnan',x:115,y:465,info:'Southwestern province; detailed records unverified.'}];
const character={"Crown Prince Jing":'Crown Prince · civil administration, economic development and institutions.', 'Prince Yan':'Imperial Prince · military reform, logistics and professional army pilot.', 'Xia Yuanji':'Senior minister associated with imperial finance and treasury administration.', 'Zhang Fu':'General · supervised Prince Yan’s 1441 training formation.', 'Yang Shiqi':'Senior court official.', 'Empress Shen':'Empress · imperial household and dynastic affairs.', 'Noble Consort Wang':'Imperial consort · inner palace.', 'Dilshad':'Palace visitor introduced in 1444; further relationship outcomes depend on player orders.', 'Ratna':'Palace visitor introduced in 1444; further relationship outcomes depend on player orders.'};
const candidateData={
 'Lady Lin':{age:23,house:'Lin family of Jiangnan',traits:['Intelligent','Ambitious','Gregarious','Proud'],skills:{Diplomacy:16,Stewardship:13,Intrigue:14,Learning:18},summary:'Politically perceptive; enjoys court discussion and seeks influence.'},
 'Lady Zhao':{age:21,house:'Zhao family of Beijing',traits:['Compassionate','Patient','Honest','Shy'],skills:{Diplomacy:12,Stewardship:15,Intrigue:5,Learning:14},summary:'A reserved scholar interested in family and household affairs.'},
 'Lady Wu':{age:25,house:'Wu family of Suzhou',traits:['Diligent','Brave','Stubborn','Scholar'],skills:{Diplomacy:14,Stewardship:17,Intrigue:11,Learning:19},summary:'Independent-minded, interested in engineering and scholarship.'}
};
const traitLibrary=['Ambitious','Brave','Calm','Compassionate','Content','Cynical','Deceitful','Diligent','Gregarious','Honest','Impatient','Just','Patient','Proud','Shy','Stubborn','Temperate','Vengeful','Zealous','Scholar','Intelligent','Loyal','Reformer'];
const skills=['Diplomacy','Martial','Stewardship','Intrigue','Learning','Prowess'];
function profileOf(name){return state.characterProfiles[name]||{traits:[],skills:{},notes:'',relationships:'',visibility:'unverified'}}
function characterIndex(){return `${info('Established campaign characters are listed below. No personality scores or private traits are asserted without evidence. You can add proposed traits and skill assessments; they remain clearly labelled as player assessments.')}${tiles(Object.keys(character))}${panel('Quick links',`<div class="actions"><button data-go="Marriage Candidates">Explore marriage candidates</button><button data-go="Appointment Council">Compare officials</button><button data-go="Character Chronicle">Relationship history</button></div>`)}`}
function badgeList(arr){return arr.length?arr.map(t=>`<span class="trait">${esc(t)}</span>`).join(' '):'<span class="muted">No traits established</span>'}
function dossier(name){let p=profileOf(name),isCandidate=!!candidateData[name],c=candidateData[name];let known=isCandidate?c.traits:p.traits;let vals=isCandidate?c.skills:p.skills;let intro=state.candidateIntroductions.includes(name);return `${isCandidate?info('FICTIONAL PROPOSAL — this marriage candidate is illustrative, not an established person in the campaign. Her skills and traits are invented for gameplay and cannot be treated as historical facts.'):info('ESTABLISHED CAMPAIGN CHARACTER — personal traits, skills and private motivations are not independently verified in the transcript unless expressly noted.')}
${panel('Character dossier',`<div class="profile-head"><div class="portrait">♟</div><div><h2>${esc(name)}</h2><p class="muted">${esc(isCandidate?c.house:character[name])}</p>${isCandidate?`<p>Age ${c.age} · ${esc(c.summary)}</p>`:''}<div class="traits">${badgeList(known)}</div></div></div>`)}
${panel(isCandidate?'Illustrative skills':'Player assessments (not canon)',`<div class="skills">${skills.map(k=>`<div class="skill"><span>${k}</span><b>${vals[k]===undefined?'?':esc(vals[k])}</b><small>${vals[k]===undefined?'Unverified':'0–30 scale'}</small></div>`).join('')}</div>${!isCandidate?`<p class="small">Add your own assessments below. These are not silently treated as confirmed historical attributes.</p>`:''}`)}
${isCandidate?panel('Marriage and courtship',`<p>Compatibility depends on observed interactions, personality and politics, not just numerical traits.</p><div class="actions"><button data-action="Arrange an introductory meeting with ${esc(name)} (fictional candidate; proposal only)">Arrange meeting</button><button data-action="Investigate the family and political connections of ${esc(name)} (fictional candidate)">Investigate family</button><button data-action="Explore marriage negotiations with ${esc(name)} (fictional candidate; no marriage concluded)">Explore marriage</button></div><p class="small">${intro?'Marked as introduced to the campaign by player proposal; awaiting simulation adjudication.':'Not introduced into campaign canon.'}</p><button class="btn" data-introduce="${esc(name)}">${intro?'Remove introduction proposal':'Propose introduction to court'}</button>`):panel('Personality & skills editor',`<p class="small">Your proposed observations are saved locally and included in save exports.</p><label class="small">Traits (comma separated)</label><input id="traitInput" class="field" value="${esc(p.traits.join(', '))}" placeholder="e.g. Diligent, Just"><div class="skills-edit">${skills.map(k=>`<label>${k}<input class="field skill-input" data-skill="${k}" type="number" min="0" max="30" value="${p.skills[k]??''}" placeholder="Unknown"></label>`).join('')}</div><label class="small">Character observations and memories</label><textarea id="charNotes" class="field" placeholder="Observed conduct, meetings, promises...">${esc(p.notes)}</textarea><label class="small">Relationships / family connections</label><textarea id="charRelations" class="field" placeholder="Known family ties, allies, rivalries...">${esc(p.relationships)}</textarea><p><button class="btn primary" data-save-profile="${esc(name)}">Save player assessment</button></p>`)}
${panel('Available interactions',`<div class="actions">${['Request private audience','Ask about ambitions','Discuss appointment','Ask for advice','Investigate loyalty','Review shared history'].map(a=>`<button data-action="${esc(a+' with '+name)}">${esc(a)}</button>`).join('')}</div>`)}
${panel('Character chronicle',state.orders.filter(o=>o.text.toLowerCase().includes(name.toLowerCase())).slice(-8).reverse().map(o=>`<div class="entry"><small>${esc(o.date)}</small><p>${esc(o.text)}</p></div>`).join('')||'<p class="muted">No new interactions recorded in this browser. Search the original Chronicle for historical events.</p>')}`}
function appointmentView(s){let roles=['Minister of Revenue','Minister of War','Provincial Governor','Diplomatic Envoy','Military Commander'];let role=roles.includes(s)?s:'Minister of Revenue';let relevant=role==='Minister of Revenue'?'Stewardship':role==='Minister of War'||role==='Military Commander'?'Martial':role==='Diplomatic Envoy'?'Diplomacy':'Stewardship';let candidates=Object.keys(character).filter(n=>!['Empress Shen','Noble Consort Wang','Dilshad','Ratna'].includes(n));return `${panel('Office selection',`<div class="actions">${roles.map(r=>`<button data-go="${esc(r)}">${esc(r)}</button>`).join('')}</div><p>Selected office: <b>${esc(role)}</b> · Primary competency: ${relevant}</p>`)}${info('Rankings use only skill values you explicitly record. Unknown values remain unranked; appointments are proposals until the game adjudicates them.')}${panel('Eligible court shortlist',`<div class="tablewrap"><table><thead><tr><th>Candidate</th><th>${relevant}</th><th>Proposed traits</th><th>Action</th></tr></thead><tbody>${candidates.sort((a,b)=>(profileOf(b).skills[relevant]??-1)-(profileOf(a).skills[relevant]??-1)).map(n=>`<tr><td><button class="linklike" data-go="${esc(n)}">${esc(n)}</button></td><td>${profileOf(n).skills[relevant]??'Unverified'}</td><td>${esc(profileOf(n).traits.join(', ')||'Unverified')}</td><td><button class="btn" data-propose-appointment="${esc(n)}" data-role="${esc(role)}">Propose</button></td></tr>`).join('')}</tbody></table></div>`)}${panel('Proposed appointments',state.appointments.length?state.appointments.slice().reverse().map(a=>`<div class="entry">${esc(a.person)} → ${esc(a.role)} <small>· Pending adjudication</small></div>`).join(''):'<p class="muted">No appointment proposals yet.</p>')}`}
function marriageView(){return `${info('The three candidates below are illustrative fictional concepts, not people already established by the 1440–1444 transcript. You can propose their introduction, meet them and investigate compatibility without assuming any marriage has taken place.')}${tiles(Object.keys(candidateData))}${panel('How marriage works',`<p>Open a candidate to inspect traits, skills, background, courtship and family investigations. Introductions and marriage negotiations are pending orders, not automatic outcomes.</p>`)}`}
function characterChronicle(){return panel('Character events & observations',`${state.orders.filter(o=>Object.keys(character).concat(Object.keys(candidateData)).some(n=>o.text.toLowerCase().includes(n.toLowerCase()))).slice().reverse().map(o=>`<div class="entry"><small>${esc(o.date)} · ${esc(o.context)}</small><div>${esc(o.text)}</div></div>`).join('')||'<p class="muted">No new character orders recorded. Historical character interactions remain in the original transcript.</p>'}`)}
function dynastyView(s){if(s==='Characters & Dynasty'||s==='Character Directory')return characterIndex();if(s==='Marriage Candidates')return marriageView();if(s==='Appointment Council'||(menu['Appointment Council']||[]).includes(s))return appointmentView(s);if(s==='Family & Succession')return `${info('Dynastic links below reflect the known campaign roles; full genealogies and marriage dates require verification.')}${tiles(menu['Family & Succession'])}`;if(s==='Character Chronicle'||s==='Recorded Audiences'||s==='Character Notes')return characterChronicle();if(candidateData[s]||character[s])return dossier(s);return ''}
const actionMap={Expenditure:['Commission an independent expenditure audit','Request military savings proposals','Review ministry-by-ministry costs'], 'Military Expenditure':['Review payroll and recruitment','Audit logistics and supply','Request equipment standardisation'],"Prince Yan's Training Formation":['Meet Prince Yan about the formation','Order a readiness inspection','Request a detailed unit roster'],Cavalry:['Inspect cavalry horses and equipment','Order cavalry manoeuvres','Review cavalry provisioning'],"Infantry & Firearms":['Inspect infantry equipment','Review firearm training','Request infantry readiness report'],"Investment House":['Convene investment directors','Review cash reserves','Request investment proposals'],"Treasury & Reserves":['Request a treasury report','Preserve the 2.5M liquidity floor','Review restricted balances'],"Empress Shen":['Request a private audience','Discuss dynastic affairs','Visit the Empress'],"Prince Yan":['Summon Prince Yan','Discuss army reforms','Assign a military planning task'],"Crown Prince Jing":['Summon Crown Prince Jing','Review economic development','Assign an institutional reform task'],"Inner Palace":['Visit the Inner Palace','Arrange a household audience'],"Steam Engines":['Review experimental steam pump','Commission a controlled trial','Request research costings']};
const panel=(title,body)=>`<section class="panel"><h3 class="section" style="margin-top:0">${esc(title)}</h3>${body}</section>`;const stat=(a,b,c='')=>`<div class="stat"><span>${esc(a)}</span><strong>${esc(b)}</strong><span>${esc(c)}</span></div>`;const tiles=items=>`<div class="grid">${items.map(x=>`<button class="tile" data-go="${esc(x)}"><span><b>${esc(x)}</b><small>${esc(subtitle(x))}</small></span><span>›</span></button>`).join('')}</div>`;function subtitle(x){const dict={'World Map':'Province selection, armies and local orders','Military':'Armies, unit types, locations and costs','Economy':'Revenue, expenditure and Crown institutions','Characters & Dynasty':'Traits, marriage, appointments and relationships','Court':'Meet ministers, appoint and instruct','Inner Palace':'Family, audiences and household affairs','Chronicle':'1440–1444 original transcript and decrees','Game & Saves':'Import, export and backup your campaign','Unit Composition':'1441 verified composition; later numbers unknown','Expenditure':'Recurring accounts, cash payments and changes','Revenue':'Annual total verified; categories not itemised','Historical Transcript':'Original campaign text, searchable'};return dict[x]||'Open records, details and orders'}
function info(text){return `<div class="notice">${text}</div>`}function rows(data){return `<div class="tablewrap"><table><tbody>${data.map(([a,b])=>`<tr><td>${esc(a)}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div>`}function actions(s){let a=actionMap[s]||[];if(character[s])a=[`Meet ${s}`,`Request a report from ${s}`,`Give ${s} an instruction`,...a];if(!a.length&&s!=='Empire')a=[`Request a report on ${s}`,`Commission an audit of ${s}`,`Propose reforms to ${s}`];return a.length?`<h3 class="section">Imperial actions</h3><div class="actions">${[...new Set(a)].map(v=>`<button data-action="${esc(v)}">${esc(v)}</button>`).join('')}</div><p class="small">Actions are recorded as proposed orders; the offline version does not invent financial or military outcomes.</p>`:''}
function overview(){let t=campaign?.treasury;return `<div class="grid">${stat('Treasury gross balance',t?money(t.grossCash)+' taels':'3.613M taels','31 Dec 1444')}${stat('Uncommitted liquidity',t?money(t.uncommittedLiquidity)+' taels':'2.633M taels','1444 closing')}${stat('Annual revenue',t?money(t.revenueAnnual)+' taels':'38.635M taels','1445 planning basis')}${stat('Annual expenditure',t?money(t.expenditureAnnualFrom1445)+' taels':'38.415M taels','1445 planned run rate')}${stat('Annual surplus',t?money(t.surplusAnnualFrom1445)+' taels':'220K taels','1445 planned run rate')}${stat('Spendable above floor',t?money(t.immediateHeadroom)+' taels':'133K taels','Before new commitments')}</div>${panel('Continue the reign · 1 January 1445',`<p>The 1440–1444 campaign is your backstory. The 1444 accounts are the last verified checkpoint. No new 1445 orders have been executed.</p><button class="btn primary" data-go="Campaign Checkpoint">Inspect imported starting position →</button>`)}${info('Treasury, companies and customer deposits remain separate. Military savings take effect in 1445; the full transcript is preserved in the Chronicle.')}`}
function mapView(){let shapes=['80,120 165,70 210,120 205,200 120,220','205,95 310,62 363,100 350,180 255,203 205,200','350,90 455,120 470,215 370,230 350,180','100,220 208,200 245,280 195,340 80,305','245,230 366,225 410,305 312,332 210,300','410,230 512,258 510,330 430,370 388,310','440,330 535,350 526,423 450,420','210,310 390,320 400,405 295,430 205,390','80,320 210,310 220,420 160,470 60,425','285,420 440,410 480,500 300,515','75,420 170,470 215,520 60,520'];return `<div class="two"><div><div class="map"><svg viewBox="0 0 600 560" role="img" aria-label="Schematic Ming provincial map"><path d="M35 80 Q180 5 350 50 Q550 50 555 220 L570 430 Q460 550 270 535 L35 530Z" fill="#2c4348" stroke="#7c887e" stroke-width="3"/>${provinces.map((p,i)=>`<polygon class="province ${p.n===selectedProvince?'sel':''}" points="${shapes[i]}" data-province="${esc(p.n)}"/><text x="${p.x}" y="${p.y}">${esc(p.n)}</text>${p.army?`<circle class="pin" cx="${p.x+48}" cy="${p.y-24}" r="9" data-province="${esc(p.n)}"/>`:''}`).join('')}</svg></div><p class="map-caption">Schematic regional selector, NOT a historically accurate province boundary map. The Beijing marker denotes the recorded 1441 formation location, not a verified 1444 deployment.</p></div>${panel(selectedProvince,`<p>${esc(provinces.find(p=>p.n===selectedProvince)?.info||'No recorded details.')}</p>${rows([['Tax revenue','Unverified'],['Population','Unverified'],['Current garrison','Unverified'],['Buildings and projects','Not fully reconciled']])}<div class="actions"><button data-action="Request a provincial report for ${esc(selectedProvince)}">Request report</button><button data-action="Review military deployments in ${esc(selectedProvince)}">Inspect forces</button><button data-action="Review investment opportunities in ${esc(selectedProvince)}">Develop province</button></div>`)}</div>`}
function military(s){if(s==='Military'||s==='Military Overview')return `<div class="grid">${stat('Professional army pilot','6,000 personnel','1444 experimental force')}${stat('Prince Yan training formation','3,000 personnel','1441 historical snapshot ONLY')}${stat('Total empire-wide troops','Unverified','No consolidated 1444 roster')}</div>${info('The 3,000-person 1441 formation and 6,000-person 1444 pilot are different dated records. They must not be added together without verification of overlap. Army costs by formation are not fully itemised.')}`;if(s==="Prince Yan's Training Formation"||s==='Formation Overview'||s==='Unit Composition')return `<div class="grid">${stat('Recorded strength','3,000','1441 only')}${stat('Location','Beijing','1441 only')}${stat('Command','Prince Yan','General Zhang Fu supervising')}</div>${rows([['Infantry & firearms','1,500'],['Cavalry','700'],['Artillery & engineers','250'],['Logistics & transport','350'],['Medical, signals & administration','200'],['Total','3,000']])}${info('These are dated 1441 figures. 1444 strength, deployment, readiness, payroll and equipment quantities are not established.')}`;const units={'Infantry & Firearms':'1,500','Cavalry':'700','Artillery & Engineers':'250','Logistics & Transport':'350','Medical, Signals & Administration':'200'};if(units[s])return `<div class="grid">${stat('Historical strength',units[s],'1441 formation')}${stat('Current strength','Unverified','1444')}${stat('Unit cost','Unverified','No payroll detail')}</div>${rows([['Historical location','Beijing (1441)'],['Commander','Not individually identified'],['Readiness','Unverified'],['Equipment inventory','Unverified'],['Supply days','Unverified']])}`;if(s==='Professional Army Pilot')return `<div class="grid">${stat('Pilot personnel','6,000','1444 recorded')}${stat('Recurring cost','Unverified','Pilot-specific budget not reconciled')}${stat('Deployment','Unverified','No confirmed location roster')}</div>`;return info('The transcript contains military development and reforms, but a current comprehensive roster, exact deployment locations, equipment inventories and unit-by-unit costs have not been verified. Use the original Chronicle to inspect source passages.')}
function economy(s){if(s==='Economy'||s==='Economic Overview')return overview();if(s==='Revenue'||s==='Revenue Overview')return `<div class="grid">${stat('Recurring annual revenue','38.635M','1443 baseline')}${stat('Verified breakdown','Unavailable','Do not infer proportions')}</div>${info('Revenue shares by land, commercial, customs and other categories are not fully reconciled. A pie chart would falsely imply known allocations.')}`;if(s==='Expenditure'||s==='Expenditure Overview')return `<div class="grid">${stat('1444 annualised baseline','38.457M','Before future savings')}${stat('1445 planned run rate','38.415M','42K savings')}${stat('Change','−42K','Effective 1445')}</div>${rows([['1443 recorded recurring expenditure','38,457,000 taels'],['Military efficiency saving certified in 1444','42,000 taels / year'],['Saving effective','1445'],['1445 planned recurring expenditure','38,415,000 taels'],['Other ministry-level recurring allocations','Not verified']])}${info('Do not treat the 1445 savings as 1444 cash. The recurring military and civil expenditure shares are unknown.')}`;if(s==='Historical Changes')return rows([['1443 annualised recurring expenditure','38,457,000'],['1444 military efficiency certification','42,000 annual saving'],['1445 annualised projected expenditure','38,415,000'],['1445 projected surplus','220,000']]);if(s==='Extraordinary Payments')return `<div class="grid">${stat('Recorded cash payments','150,000','1444 listed items')}${stat('Prior commitments settled','40,000','Not a new programme')}</div>${rows([['Industrial Academy & steam research','40,000'],['Military efficiency & logistics','35,000'],['Agricultural technical improvements','20,000'],['Independent military audit','10,000'],['Diplomatic & household missions','5,000'],['Settlement of previous commitments','40,000'],['TOTAL','150,000']])}${info('These are separately recorded extraordinary cash payments. They should not be added to the recurring annualised budget without a complete reconciliation.')}`;const extra={'Industrial Academy & Steam':'40,000','Military Logistics Reform':'35,000','Agricultural Improvements':'20,000','Military Audit':'10,000','Diplomatic & Household Missions':'5,000','Prior Commitments':'40,000'};if(extra[s])return rows([['1444 recorded cash payment',extra[s]+' taels'],['Budget treatment',s==='Prior Commitments'?'Settlement of previous commitments':'Extraordinary cash expenditure'],['Project-level itemisation','Unverified']]);if(s==='Treasury & Reserves'||s==='Treasury Overview')return `<div class="grid">${stat('Opening gross balances','3.585M','1444')}${stat('Opening commitments','0.475M','1444')}${stat('Opening restricted reserves','0.520M','1444')}${stat('Opening uncommitted','2.590M','1444')}${stat('Later gross balances','3.613M','1444')}${stat('Later uncommitted','2.633M','1444')}</div>${info('Treasury minimum liquidity floor: 2.5M taels. Company cash, assets and bank deposits are not interchangeable with uncommitted Treasury liquidity.')}`;if(s==='Investment House'||s==='Company Overview'||s==='Cash & Assets')return `<div class="grid">${stat('Opening company assets','2.404136M','1444')}${stat('Opening cash','247,136','1444')}${stat('Later assets','2.494184M','1444')}${stat('Later cash','277,184','1444')}</div>${info('Investment House is accounted for separately from the imperial Treasury. Do not add company assets to liquid Treasury cash.')}`;if(s==='Mining Company'||s==='Mining Overview')return `<div class="grid">${stat('Opening company assets','1.935M','1444')}${stat('Opening company cash','204,000','1444')}</div>`;if(s==="Soldiers' Bank"||s==='Bank Overview')return `<div class="grid">${stat('Customer deposits','2.070M','1444 opening')}${stat('Accounting treatment','Liability','Not Crown cash')}</div>`;if(['Recurring Expenditure','Military Recurring Costs','Civil Recurring Costs','Other Recurring Costs','Public Works & Industry','Civil Administration'].includes(s))return info('The detailed allocation for this recurring expenditure category is not verified. The known total is 38.457M taels annually at the 1444 baseline, falling by 42K from 1445. Request an audit to develop an itemised budget without inventing figures.');return info('The original campaign records this area, but detailed current financial amounts have not been reconciled. Search the Chronicle for dated entries before taking an accounting decision.')}
function characterView(s){return `<div class="grid">${stat('Character',s,'Campaign person')}${stat('Status','Historical record','Details vary by character')}</div>${panel('Profile',`<p>${esc(character[s])}</p>${rows([['Current location','Unverified'],['Personal relationship score','Not quantified'],['Last audience','See original Chronicle'],['New instructions','Recorded in local orders']])}`)}`}
function other(s){if(s==='Technology'||s==='Steam Engines')return `${info('The 1444 campaign includes an experimental steam pump and continuing industrial research. Operational output, return on investment and engineering success must be verified through the Chronicle.')}`;if(s==='Institutions'||s==='Institution Register')return `${info('Crown companies, ministries and new institutions can be tracked here. Custom institutions created by decree appear in the register.')}${state.custom.length?tiles(state.custom.map(x=>x.name)):''}`;if(s==='Create Institution')return `<label class="small">Institution name</label><input id="entityName" class="field" placeholder="e.g. Imperial Canal Authority"><label class="small">Mandate</label><textarea id="entityMandate" class="field" placeholder="Describe responsibilities and proposed funding"></textarea><p><button class="btn primary" id="createEntity">Create proposed institution</button></p>${info('Creation records a proposed institution. No funds are spent or officials appointed automatically.')}`;if(state.custom.some(x=>x.name===s)){const e=state.custom.find(x=>x.name===s);return panel('Institution dossier',`<p>${esc(e.mandate)}</p>${rows([['Status','Proposed; awaiting imperial implementation'],['Funds allocated','None verified'],['Created',e.date]])}`)}return info('Open the Chronicle to examine the full campaign history. This screen contains only verified summary details; unknown facts are not automatically fabricated.')}
function chronicle(s){if(s==='Chronicle'||s==='Timeline & Orders')return `<div class="grid">${stat('Historical chapters','1440–1444','Bundled original transcript')}${stat('Recorded new orders',String(state.orders.length),'Saved in this browser')}</div>${panel('Recent imperial decrees',state.orders.length?state.orders.slice().reverse().slice(0,15).map(o=>`<div class="entry"><small>${esc(o.date)} · ${esc(o.context)}</small><div>${esc(o.text)}</div><small>Status: ${esc(o.status)}</small>${aiResult(o)}</div>`).join(''):'<p class="muted">No new decrees issued in this browser.</p>')}`;if(s==='Historical Transcript'||s==='Search Chronicle'||/^144[0-4]$/.test(s)){let q=search||( /^144[0-4]$/.test(s)?s:'');let source=state.transcript||archive;let hits=[];if(q&&source){let re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'ig'),m;while((m=re.exec(source))&&hits.length<80){let start=Math.max(0,m.index-180),end=Math.min(source.length,m.index+320);hits.push({index:m.index,text:source.slice(start,end)});if(!m[0].length)re.lastIndex++}}return `<div class="panel"><div class="row"><input class="field" style="flex:1;min-width:160px" id="chronicleSearch" placeholder="Search people, year, battles, accounts…" value="${esc(search)}"><button class="btn" id="searchBtn">Search</button></div><p class="small">${esc(archiveStatus)} · ${money(source.length)} characters loaded. Search returns contextual extracts, not a reconciled database.</p><div class="searchresults">${q?(hits.length?hits.map(h=>`<div class="entry"><small>Character offset ${money(h.index)}</small><div>${esc(h.text)}</div></div>`).join(''):'<p class="muted">No matches found.</p>'):'<p class="muted">Enter a search term or choose a year. The original transcript is included in this download.</p>'}</div></div>`}return ''}
function saves(s){if(s==='AI Connection')return `${panel('Connect the AI Game Master',`<p>Enter your Cloudflare Worker URL and the GAME_ACCESS_TOKEN you configured as a Cloudflare secret. The token is stored only for this browser tab session; do not share it or commit it to GitHub.</p><label class="small">Cloudflare Worker URL</label><input class="field" id="aiEndpoint" value="${esc(aiEndpoint)}" placeholder="https://your-worker.workers.dev"><label class="small">Game access token</label><input class="field" type="password" id="aiToken" value="${esc(aiToken)}" placeholder="Enter the secret token"><div class="actions"><button class="btn primary" id="saveAi">Save connection for this tab</button><button class="btn" id="testAi">Test Worker health</button><button class="btn" id="clearAi">Clear token</button></div><p class="small" id="aiConnectionStatus">The health check tests Worker availability, not API billing or token validity. For full verification, issue a decree.</p><p class="small">Security: this is a public GitHub Pages frontend. A shared access token entered into the browser is not strong protection against misuse. Keep API usage limits and Cloudflare rate limits in place before regular use.</p>`)}`;if(s==='Game & Saves'||s==='About & Limitations')return `${panel('Save and install',`<p>This is an offline-first PWA. On iPhone, visit a hosted HTTPS URL in Safari, tap Share → Add to Home Screen. For Mac, open the hosted URL in a browser. Local browser saves do not automatically sync between devices.</p><p>To move a save between iPhone and Mac, export it and import it on the other device. A cloud sync service requires a later backend deployment.</p>`)}${panel('Gameplay engine',`<p>Menus, navigation, chronicle search, decree logging, and custom institution proposals work now. The AI Game Master can respond to natural-language orders when configured. Its proposed changes are displayed for review and are <b>not automatically applied</b> to campaign accounts, troops, or character records.</p>`)}`;if(s==='Export Save')return `<p>Download a JSON backup containing new orders, custom institutions and local campaign state.</p><button class="btn primary" id="exportBtn">Download campaign save</button>`;if(s==='Import Save')return `<p>Select a previously exported Dragon Throne JSON save. This replaces the current browser save.</p><input type="file" accept="application/json,.json" id="importSave" class="field">`;if(s==='Import Transcript')return `<p>Replace the searchable Chronicle with your own plain-text transcript. This imports the text as an archive; it does not automatically extract or reconcile game-state entities.</p><input type="file" accept="text/plain,.txt" id="importTranscript" class="field">`;return ''}
function checkpointView(s){if(!campaign)return info('Loading campaign checkpoint from bundled campaign.json. If this persists, use GitHub Pages rather than opening index.html directly.');const t=campaign.treasury, moneyT=n=>money(n)+' taels';if(s==='Campaign Checkpoint'||s==='Start 1445')return `${panel('Your reign continues on 1 January 1445',`<p>1440–1444 is already part of the campaign. No new 1445 decisions have been simulated. The full original transcript remains available in Chronicle.</p><p><b>Current imperial agenda:</b> ${campaign.agenda1445.map(a=>esc(a.area)).join(' · ')}</p>`)}<div class="grid">${stat('Treasury cash',moneyT(t.grossCash),'31 December 1444')}${stat('Spendable above floor',moneyT(t.immediateHeadroom),'Before further commitments')}${stat('Professional army pilot','6,000','Expansion not authorised')}${stat('1445 annual surplus',moneyT(t.surplusAnnualFrom1445),'Projected run rate')}</div>${panel('Verified historical events',campaign.events.map(e=>`<div class="entry"><small>${e.year}</small><b>${esc(e.title)}</b><p>${esc(e.summary)}</p></div>`).join(''))}`;if(s==='1444 Closing Accounts')return `<div class="grid">${stat('Gross Treasury cash',moneyT(t.grossCash),'Closing')}${stat('Uncommitted liquidity',moneyT(t.uncommittedLiquidity),'Closing')}${stat('Warrants',moneyT(t.commitments),'Outstanding')}${stat('Restricted reserves',moneyT(t.restrictedReserves),'Restricted')}${stat('Liquidity floor',moneyT(t.minimumLiquidity),'Policy')}${stat('Headroom',moneyT(t.immediateHeadroom),'Available above floor')}</div>${panel('Treasury reconciliation',rows([['Opening gross cash',moneyT(campaign.cashMovement1444.opening)],['Operating surplus',moneyT(campaign.cashMovement1444.operatingSurplus)],...campaign.cashMovement1444.payments.map(p=>[p.name,'−'+moneyT(p.amount)]),['Closing gross cash',moneyT(campaign.cashMovement1444.closing)]]))}${info('1445 expenditure of 38.415M is an annualised run rate; 42,000 taels in military savings are not retroactive 1444 cash.')}`;if(s==='1445 Council Agenda')return campaign.agenda1445.map(a=>panel(a.area,`<p>${esc(a.text)}</p><button data-action="Request implementation options for ${esc(a.area)} 1445 programme, preserving verified treasury and approval limits">Request options</button>`)).join('');if(s==='Recorded Characters')return `${panel('Known people · traits not invented',campaign.characters.map(c=>`<div class="entry"><b>${esc(c.name)}</b><p>${esc(c.known)}</p></div>`).join(''))}${info('Use Characters & Dynasty to record personal assessments and new interactions. No unrecorded traits or marriage outcomes are assumed.')}`;if(s==='Known Unknowns')return panel('Not established in the transcript',`<ul>${campaign.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`);return ''}
function visualTheme(s){let group=path.find(p=>['Military','Economy','Court','Characters & Dynasty','Inner Palace','Technology','Diplomacy','Institutions','Chronicle'].includes(p));if(s==='Empire'||s==='World Map')return ['map','The Empire Awaits','Survey the realm, examine its provinces and issue imperial orders.'];if(group==='Military')return ['military','The Imperial Armies','Regiments, commanders, equipment, logistics and reform.'];if(group==='Economy')return ['economy','The Imperial Exchequer','Revenue, expenditure, reserves and Crown enterprises.'];if(group==='Court'||group==='Characters & Dynasty')return ['court','The Imperial Court','Officials, traits, loyalties, appointments and dynastic ties.'];if(group==='Inner Palace')return ['palace','The Inner Palace','Household affairs, relationships and audiences.'];if(group==='Technology'||group==='Institutions')return ['scholar','Knowledge & Institutions','Scholarship, inventions, reforms and new establishments.'];if(group==='Diplomacy')return ['map','Foreign Affairs','Envoys, treaties, trade routes and frontier policy.'];return ['scholar','The Imperial Chronicle','Review the decisions and records of the reign.']}
function hero(s){let [img,title,desc]=visualTheme(s);return `<section class="hero" aria-label="${esc(title)}"><img class="hero-art" src="assets/${img}.svg" alt="" loading="eager"><div class="hero-shade"></div><div class="hero-body"><div class="hero-kicker">The Great Ming · Imperial Edition</div><h2>${esc(s==='Empire'?title:s)}</h2><p>${esc(desc)}</p></div><div class="hero-ornament">◆ ◆ ◆</div></section>`}
function render(){let s=path.at(-1),content='';if(s==='Empire')content=overview()+`<h3 class="section">Imperial departments</h3>`+tiles(menu.Empire)+`<h3 class="section">Provincial map</h3>`+mapView();else{if(s==='World Map')content=mapView();else if(s==='Campaign Checkpoint'||path.includes('Campaign Checkpoint'))content=checkpointView(s);else if(s==='Military'||path.includes('Military'))content=military(s);else if(s==='Economy'||path.includes('Economy'))content=economy(s);else if(s==='Characters & Dynasty'||path.includes('Characters & Dynasty')||candidateData[s])content=dynastyView(s);else if(character[s])content=characterView(s);else if(s==='Chronicle'||path.includes('Chronicle'))content=chronicle(s);else if(s==='Game & Saves'||path.includes('Game & Saves'))content=saves(s);else content=other(s);if(menu[s])content+=`<h3 class="section">${s==='Empire'?'Departments':'Explore '+esc(s)}</h3>`+tiles(menu[s]);if(s==='Court'||s==='Inner Palace')content+=info('Select a named character for their dossier, then issue an audience request or instruction. Dialogue generation requires an AI backend.');if(s==='Institutions')content+=state.custom.length?`<h3 class="section">New institutions</h3>`+tiles(state.custom.map(e=>e.name)):'';content+=actions(s)}
const nav=['World Map','Military','Economy','Court','Characters & Dynasty','Inner Palace','Chronicle'];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">♛ Dragon Throne</div><div class="small" style="padding-left:10px">MING IMPERIAL COMMAND · 1445</div><nav class="nav">${menu.Empire.map(n=>`<button class="${path.includes(n)?'active':''}" data-root="${esc(n)}">${esc(n)}</button>`).join('')}</nav><p class="footer">Offline-first · No Lovable credits<br>Save stays on this device until exported.</p></aside><main class="main"><header class="top"><div><div class="small">THE GREAT MING · ALTERNATE HISTORY</div><h1>${esc(s==='Empire'?'The Imperial Throne':s)}</h1></div><span class="pill">${state.year} · ${state.orders.length} new orders</span></header><div class="breadcrumbs"><button class="back" id="backBtn" ${path.length===1?'disabled':''}>← Back</button><button data-home="1">⌂ Main menu</button>${path.map((p,i)=>`<span class="small">›</span><button data-crumb="${i}">${esc(p)}</button>`).join('')}</div>${hero(s)}${content}<div class="order"><label class="tag">Unrestricted imperial decree · ${esc(s)}</label><textarea id="decree" class="field" placeholder="Issue any order: meet a minister, inspect troops, establish an institution, reform taxation…"></textarea><div class="row" style="justify-content:space-between;margin-top:8px"><span class="small">AI connected when a Worker URL and token are configured. AI suggestions are reviewed, not automatically enacted.</span><button class="btn primary" id="issue">Send decree to AI</button></div></div><p class="footer">Source: bundled 1440–1444 transcript and verified checkpoint. Unverified figures remain unknown. <button class="btn" data-root="Game & Saves">Export or import save</button></p></main></div><nav class="mobile-nav">${['World Map','Military','Economy','Court','Inner Palace','Chronicle'].map(n=>`<button class="${path.includes(n)?'active':''}" data-root="${esc(n)}">${({'World Map':'🗺️ Map','Military':'⚔ Army','Economy':'◈ Economy','Court':'♜ Court','Characters & Dynasty':'♙ People','Inner Palace':'♥ Palace','Chronicle':'☷ History'})[n]}</button>`).join('')}</nav>`;bind()}
async function record(text){
  text=String(text||'').trim();if(!text||aiBusy)return;
  const contextPath=path.join(' > ');
  const order={text,context:contextPath,date:`${state.year} · order ${state.orders.length+1}`,status:'Pending adjudication'};
  state.orders.push(order);persist();
  if(!aiToken){root('AI Connection');alert('Decree saved as pending. Enter your GAME_ACCESS_TOKEN under AI Connection, then return to Chronicle to retry it.');return;}
  await adjudicate(order);
}
async function adjudicate(order){
  if(aiBusy)return;aiBusy=true;
  const button=$('#issue');if(button){button.disabled=true;button.textContent='Awaiting AI…';}
  try{
    const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),60000);
    let response;
    try{response=await fetch(aiEndpoint.replace(/\/$/,'')+'/adjudicate',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+aiToken},body:JSON.stringify({command:order.text,context:{year:state.year,month:state.month,turn:state.turn,department:order.context,checkpoint:campaign?{treasury:campaign.treasury,agenda1445:campaign.agenda1445}:null,previousOrders:state.orders.slice(-12).map(o=>({text:o.text,status:o.status})),characterProfiles:state.characterProfiles,appointments:state.appointments,customInstitutions:state.custom},history:state.history.slice(-8).flatMap(h=>h.messages||[])}),signal:controller.signal});}finally{clearTimeout(timeout)}
    let payload;try{payload=await response.json()}catch{throw Error('Worker returned a non-JSON response (HTTP '+response.status+').')}
    if(!response.ok)throw Error((payload.error||'Worker request failed')+' (HTTP '+response.status+(payload.status?', provider '+payload.status:'')+').');
    const result=payload.result;if(!result||typeof result.narrative!=='string')throw Error('AI response lacked a narrative.');
    order.status='AI response received — changes not applied';
    order.adjudication={narrative:result.narrative,developments:Array.isArray(result.developments)?result.developments:[],proposed_changes:Array.isArray(result.proposed_changes)?result.proposed_changes:[],pending_decisions:Array.isArray(result.pending_decisions)?result.pending_decisions:[],chronicle_entry:String(result.chronicle_entry||''),usage:payload.usage||null};
    state.history.push({messages:[{role:'user',content:order.text},{role:'assistant',content:result.narrative}]});
    persist();root('Chronicle');
  }catch(err){order.status='Pending adjudication — '+err.message;persist();root('Chronicle');alert('Decree saved, but AI could not complete: '+err.message+'\nYou can retry from Chronicle.');}
  finally{aiBusy=false;}
}
function aiResult(order){let a=order.adjudication;if(!a)return `<button class="btn" data-retry-order="${state.orders.indexOf(order)}">Retry with AI</button>`;return `<div class="ai-result"><p><b>AI Game Master</b></p><p>${esc(a.narrative)}</p>${a.developments.length?`<b>Developments</b><ul>${a.developments.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${a.proposed_changes.length?`<b>Proposed changes — NOT APPLIED</b><ul>${a.proposed_changes.map(x=>`<li>${esc(x.path||'Unspecified')}: ${esc(JSON.stringify(x.old_value))} → ${esc(JSON.stringify(x.new_value))} (${esc(x.reason||'')})</li>`).join('')}</ul>`:''}${a.pending_decisions.length?`<b>Pending decisions</b><ul>${a.pending_decisions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${a.chronicle_entry?`<p><b>Chronicle:</b> ${esc(a.chronicle_entry)}</p>`:''}</div>`}

function download(name,data,type){let url=URL.createObjectURL(new Blob([data],{type}));let a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-root]').forEach(b=>b.onclick=()=>root(b.dataset.root));document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{path=['Empire'];render()});document.querySelectorAll('[data-crumb]').forEach(b=>b.onclick=()=>{path=path.slice(0,Number(b.dataset.crumb)+1);render()});$('#backBtn').onclick=back;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{$('#decree').value=b.dataset.action;$('#decree').focus();$('#decree').scrollIntoView({behavior:'smooth',block:'center'})});document.querySelectorAll('[data-province]').forEach(b=>b.onclick=()=>{selectedProvince=b.dataset.province;render()});$('#issue').onclick=()=>record($('#decree').value);document.querySelectorAll('[data-retry-order]').forEach(b=>b.onclick=()=>{if(!aiToken){root('AI Connection');alert('Set your access token first.');return;}const o=state.orders[Number(b.dataset.retryOrder)];if(o)adjudicate(o)});if($('#saveAi'))$('#saveAi').onclick=()=>{const url=$('#aiEndpoint').value.trim().replace(/\/$/,'');if(!/^https:\/\/[^/]+$/i.test(url))return alert('Enter the HTTPS Worker origin only, without /health or /adjudicate.');aiEndpoint=url;aiToken=$('#aiToken').value.trim();sessionStorage.setItem('dragon-throne-ai-endpoint',aiEndpoint);sessionStorage.setItem('dragon-throne-ai-token',aiToken);$('#aiConnectionStatus').textContent='Connection saved for this tab. Return to the Empire and issue a decree.'};if($('#clearAi'))$('#clearAi').onclick=()=>{aiToken='';sessionStorage.removeItem('dragon-throne-ai-token');$('#aiToken').value='';$('#aiConnectionStatus').textContent='Token cleared.'};if($('#testAi'))$('#testAi').onclick=async()=>{try{const url=$('#aiEndpoint').value.trim().replace(/\/$/,'');const r=await fetch(url+'/health');const j=await r.json();$('#aiConnectionStatus').textContent=r.ok&&j.ok?'Worker is online. Save your token and issue a decree to test AI.':'Worker returned HTTP '+r.status;}catch(e){$('#aiConnectionStatus').textContent='Health check failed: '+e.message}};document.querySelectorAll('[data-save-profile]').forEach(b=>b.onclick=()=>{let name=b.dataset.saveProfile;let traits=$('#traitInput').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,20);let skillsData={};document.querySelectorAll('[data-skill]').forEach(el=>{if(el.value.trim()!==''){let v=Number(el.value);if(!Number.isInteger(v)||v<0||v>30)return;skillsData[el.dataset.skill]=v}});state.characterProfiles[name]={traits,skills:skillsData,notes:$('#charNotes').value,relationships:$('#charRelations').value,visibility:'player assessment'};persist();render();alert('Player assessment saved. Not asserted as historical canon.');});document.querySelectorAll('[data-introduce]').forEach(b=>b.onclick=()=>{let n=b.dataset.introduce;if(state.candidateIntroductions.includes(n))state.candidateIntroductions=state.candidateIntroductions.filter(x=>x!==n);else{state.candidateIntroductions.push(n);state.orders.push({text:'Propose introducing fictional candidate '+n+' to court; no relationship or marriage outcome determined',context:path.join(' > '),date:String(state.year)+' · order '+(state.orders.length+1),status:'Pending adjudication'});}persist();render()});document.querySelectorAll('[data-propose-appointment]').forEach(b=>b.onclick=()=>{let person=b.dataset.proposeAppointment,role=b.dataset.role;if(!confirm('Record proposal to appoint '+person+' as '+role+'? This does not execute the appointment.'))return;state.appointments.push({person,role,status:'Pending adjudication'});state.orders.push({text:'Propose appointment: '+person+' as '+role+'. Assess suitability, politics and confirmation before enactment.',context:path.join(' > '),date:String(state.year)+' · order '+(state.orders.length+1),status:'Pending adjudication'});persist();render()});if($('#createEntity'))$('#createEntity').onclick=()=>{let name=$('#entityName').value.trim(),mandate=$('#entityMandate').value.trim();if(!name||!mandate)return alert('Enter a name and mandate.');if(state.custom.some(e=>e.name===name)||menu[name])return alert('That institution already exists.');state.custom.push({name,mandate,date:String(state.year)+' · proposed'});state.orders.push({text:`Propose institution: ${name}. Mandate: ${mandate}`,context:'Institutions',date:String(state.year),status:'Pending adjudication'});persist();root('Institutions')};if($('#searchBtn'))$('#searchBtn').onclick=()=>{search=$('#chronicleSearch').value.trim();render()};if($('#chronicleSearch'))$('#chronicleSearch').onkeydown=e=>{if(e.key==='Enter'){$('#searchBtn').click()}};if($('#exportBtn'))$('#exportBtn').onclick=()=>download('dragon-throne-save.json',JSON.stringify(state,null,2),'application/json');if($('#importSave'))$('#importSave').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let data=JSON.parse(await f.text());if(!Array.isArray(data.orders)||!Array.isArray(data.custom))throw Error('Invalid save format');if(confirm('Replace the current local campaign save?')){state={...BASE,...data};persist();path=['Empire'];render()}}catch(err){alert('Unable to import save: '+err.message)}};if($('#importTranscript'))$('#importTranscript').onchange=async e=>{let f=e.target.files[0];if(!f)return;state.transcript=await f.text();persist();search='';root('Chronicle');go('Historical Transcript')}}
fetch('./campaign.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(c=>{campaign=c;render()}).catch(()=>{console.warn('Campaign checkpoint could not be loaded')});fetch('./chronicle.txt').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.text()}).then(t=>{archive=t;archiveStatus='Bundled original transcript';if(path.includes('Chronicle'))render()}).catch(()=>{archiveStatus='Bundled transcript unavailable via file://; use a local server or hosted site';if(path.includes('Chronicle'))render()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});render();
})();
